document.addEventListener("DOMContentLoaded",(async()=>{const e=await fetch("/api/get-all-events");if(!e.ok)throw new Error(`Failed fetching event data! ${e.status}`);const t=await e.json(),o=document.getElementById("example-photo-card"),r=document.getElementById("photo-card-container");for(const[e,n]of t.entries()){const t=o.cloneNode(!0);t.removeAttribute("id"),t.classList.remove("d-none");const a=t.querySelector("#example-photo-card-title"),c=t.querySelector("#example-photo-card-desc"),d=t.querySelector("#example-photo-card-date"),i=t.querySelector("#example-photo-card-cover"),l=t.querySelector("#example-photo-card-button"),s=t.querySelector("#example-photo-card-modal");a.removeAttribute("id"),c.removeAttribute("id"),d.removeAttribute("id"),i.removeAttribute("id"),l.removeAttribute("id"),a.textContent=n.title,c.textContent=n.desc,d.textContent=n.date,i.src=n.cover,s.id=`modal-event-${e}`,l.dataset.bsTarget=s.id,s.querySelector(".modal-title").textContent=`${n.title} - ${n.date}`;const m=s.querySelector("#example-modal-image");for(const e of n.photos){const t=m.cloneNode(!0);t.removeAttribute("id"),t.classList.remove("invisible-intangible"),t.querySelector("a").href=e,t.querySelector("img").src=e,m.parentElement.appendChild(t)}m.remove(),r.appendChild(t)}if(o.remove(),0===t.length){const e=document.createElement("p");e.innerText="No photos yet, check back later!",e.classList.add("text-center"),r.appendChild(e),r.classList.add("d-flex","justify-content-center","align-items-center")}}));